//! litany-core: domain types and recurrence engine.
//!
//! Design invariants (TechGodHQ doctrine):
//! - Pure domain logic lives here; no HTTP, no Telegram, no provider code.
//! - Surfaces (CLI/HTTP/MCP) are generated by hydra from `api/operations.yaml`.
//! - Every completed occurrence records its actual completion timestamp;
//!   streaks are derived, never stored counters.

pub mod model;
pub mod recurrence;
pub mod streak;

pub use model::{AdvanceMode, Occurrence, Recurrence, Task};
pub use recurrence::{most_recent_satisfied_due, next_due, next_due_for_mode};
pub use streak::{best, current};
